package main

import (
	"encoding/hex"
	"fmt"
)

// These lookup tables and the transform match the legacy vSRO client skill
// data format. The algorithm was independently verified against the local
// vSRO 1.188 Media files.
var (
	skillHashTable1 = mustDecodeSkillTable("")
	skillHashTable2 = mustDecodeSkillTable("")
)

func encryptSkillData(plain []byte) []byte {
	encrypted := make([]byte, len(plain), len(plain)+20)
	copy(encrypted, plain)
	key := uint32(0x8C1F)
	for index := range encrypted {
		delta := skillHashTable1[key%0xA7] - skillHashTable2[key%0x1EF]
		encrypted[index] -= delta
		key++
	}
	// UTF-16LE without a BOM, matching the client format.
	encrypted = append(encrypted, '\r', 0, '\n', 0, '/', 0, '/', 0, 'e', 0, 'n', 0, 'c', 0, 'r', 0, 'y', 0, 'p', 0, 't', 0)
	return encrypted
}

func mustDecodeSkillTable(value string) []byte {
	decoded, err := hex.DecodeString(value)
	if err != nil {
		panic(fmt.Sprintf("decode embedded skill encryption table: %v", err))
	}
	return decoded
}
